"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_MIN_WIDTH = 3
_DELIMITER = re.compile(r":?-+:?")


def _escape(value) -> str:
    """Cell text with pipes escaped and ``None`` rendered empty."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    """Pad ``text`` to ``width`` according to ``alignment``."""
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter(width: int, alignment: str | None) -> str:
    """Delimiter cell of ``width`` dashes with alignment colons."""
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _unescape(text: str) -> str:
    return text.replace("\\|", "|")


def _split_cells(line: str) -> list[str]:
    """Split a stripped line on unescaped pipes.

    A pipe is escaped when it is immediately preceded by a backslash.  This
    deliberately does not count backslashes: ``\\\\|`` (two backslashes and
    a pipe) is still treated as escaped, because ``format_table`` escapes
    every pipe by inserting exactly one backslash before it.  Consequently
    a cell whose text ends with a backslash cannot be represented
    unambiguously when the surrounding spaces are omitted.
    """
    cells: list[str] = []
    start = 0
    for index, character in enumerate(line):
        if character == "|" and not (index and line[index - 1] == "\\"):
            cells.append(line[start:index])
            start = index + 1
    cells.append(line[start:])
    return cells


def _parse_row(line: str) -> list[str]:
    """Parse one line into stripped, unescaped cells."""
    stripped = line.strip()
    cells = _split_cells(stripped)
    if stripped.startswith("|"):
        cells = cells[1:]
    if stripped.endswith("|") and not (
        len(stripped) > 1 and stripped[-2] == "\\"
    ):
        cells = cells[:-1]
    return [_unescape(cell.strip()) for cell in cells]


def _parse_delimiter(cell: str) -> str | None:
    """Return the alignment described by a delimiter cell."""
    if not _DELIMITER.fullmatch(cell):
        raise ValueError(f"invalid delimiter cell: {cell!r}")
    left = cell.startswith(":")
    right = cell.endswith(":")
    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table.

    An empty header is rejected with ``ValueError``: a table with no
    columns has no meaningful delimiter line, and ``parse_table`` could
    not distinguish it from a one-column table of empty cells.
    """
    if not header:
        raise ValueError("header must have at least one column")

    if align is None:
        alignments: list[str | None] = [None] * len(header)
    else:
        try:
            alignments = list(align)
        except TypeError:
            raise ValueError("align must be a sequence of alignments") from None
        if len(alignments) != len(header):
            raise ValueError(
                f"align has {len(alignments)} entries for "
                f"{len(header)} columns"
            )
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_escape(value) for value in header]
    body: list[list[str]] = []
    for row in rows:
        if len(row) > len(header):
            raise ValueError(
                f"row has {len(row)} cells for {len(header)} columns"
            )
        cells = [_escape(value) for value in row]
        cells.extend([""] * (len(header) - len(cells)))
        body.append(cells)

    widths = [
        max(
            [_MIN_WIDTH, len(header_cells[column])]
            + [len(row[column]) for row in body]
        )
        for column in range(len(header))
    ]

    def write(cells: list[str], *, delimiter: bool = False) -> str:
        if delimiter:
            rendered = [_delimiter(widths[i], alignments[i]) for i in range(len(cells))]
        else:
            rendered = [
                _pad(cells[i], widths[i], alignments[i])
                for i in range(len(cells))
            ]
        return "| " + " | ".join(rendered) + " |"

    lines = [write(header_cells), write(header_cells, delimiter=True)]
    lines.extend(write(row) for row in body)
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments.

    Lines are split with ``str.splitlines``, so a single trailing newline is
    accepted.  Blank lines are not rows and raise ``ValueError``.  Outer
    pipes are optional, and a pipe preceded by a backslash is treated as
    literal text; see ``_split_cells`` for the resulting ``\\\\|``
    ambiguity.
    """
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs at least a header and delimiter line")
    for lineno, line in enumerate(lines, 1):
        if not line.strip():
            raise ValueError(f"line {lineno}: blank line in table")

    header = _parse_row(lines[0])
    if not header:
        raise ValueError("header has no columns")

    alignments = [_parse_delimiter(cell) for cell in _parse_row(lines[1])]
    if len(alignments) != len(header):
        raise ValueError(
            f"delimiter line has {len(alignments)} cells for "
            f"{len(header)} columns"
        )

    rows: list[list[str]] = []
    for lineno, line in enumerate(lines[2:], 3):
        cells = _parse_row(line)
        if len(cells) != len(header):
            raise ValueError(
                f"line {lineno} has {len(cells)} cells for "
                f"{len(header)} columns"
            )
        rows.append(cells)

    return header, rows, alignments

